// TH14 v1.00b Stage 3 wave 1 (th14_s3_w01).
// Entry: st03.ecl.txt::MainSub00 485-497. Card frame 0 = phase start;
// source frame 0 begins at card frame OPENING_BUFFER.
// Closures kept: MainSub00b/c, Phantom01(+_at), ECir00(+_at). Phantom01_at2
// (death callback) is unreachable under the invulnerable no-DPS shell and is
// omitted, see report.md.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// Source ECir00_at uses the emitter sprite for the Line; the target laser has
// its own texture, so only the source color (etSprite(...,3)) is kept.
const LASER_COLOR: int = 3;

// Phantom01_at: !HL only. Initial diffWait then one aimed shot, then difWait
// + etOn repeated $A times (Easy 0 / Normal 1 / Hard 4 / Lunatic 8).
// The whole task is spawned for Hard/Lunatic only (source mask !HL).
async sub phantom01_fire() {
    var first: int = 0;
    var extra: int = 0;
    if global(GVAR_RANK) >= RANK_LUNATIC {
        first = 40 + rand(40);
        extra = 8;
    } else {
        first = 60 + rand(40);
        extra = 4;
    }
    wait(first);
    // etAim(0,0) fan, one way one layer, speed 2 (M=1 takes speed0), type 5 color 6.
    _ = fire(TH14_BALL2, 6, $self_x, $self_y, 2fx, aim_player(), none, none);
    for i in 0..extra {
        wait(60 + rand(20));
        _ = fire(TH14_BALL2, 6, $self_x, $self_y, 2fx, aim_player(), none, none);
    }
}

// Phantom01: setHurtbox(28,28)=r14, setHitbox(16,16)=r8.
// Movement is the source ABS moveVel(0,1) plus the REL circle:
// moveCircleRel(RANDRAD, 1deg/frame, 0, 0) with radius 0->16 over 80 frames.
// Final position = ABS + REL; the parent mirror flips only the ABS moveVel
// direction, not the circle layer.
async sub phantom01(mirror: int, firing: int) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    if firing == 1 {
        spawn phantom01_fire();
    }
    var dir: fx = 1fx;
    if mirror == 1 {
        dir = 0fx - 1fx;
    }
    var bx: fx = $self_x;
    var by: fx = $self_y;
    var theta: angle = rand(65536) as angle;
    var t: int = 0;
    loop {
        t = t + 1;
        bx = bx + dir;
        theta = theta + 1deg;
        var r: fx = 16fx;
        if t < 80 {
            r = (t as fx) * 0.2fx;
        }
        move_to(0, bx + r * cos(theta), by + r * sin(theta), EASE_LINEAR);
        wait(1);
    }
}

// MainSub00b / MainSub00c: 10 Phantom01 per side, every 40 frames; right side
// starts 20 frames later and uses enmCreateM (mirror). y = 64 + RANDF*128.
async sub phantom_stream_left(firing: int) {
    for i in 0..10 {
        _ = spawn_enemy(-192fx, 64fx + (rand(128) as fx), 130, 0, 0, 0, phantom01(0, firing));
        wait(40);
    }
}
async sub phantom_stream_right(firing: int) {
    wait(20);
    for i in 0..10 {
        _ = spawn_enemy(192fx, 64fx + (rand(128) as fx), 130, 0, 0, 0, phantom01(1, firing));
        wait(40);
    }
}

// ECir00_at: Line laser fan. Source etAngle sets the base angle, etSpeed names
// the Line travel speed, laserNew(0,L,0,14) with L by rank, laserOn repeats
// $B times with per-rank gap. Line judgment: start=0.1L,end=0.9L of the line,
// half height w/4; modelled as a rod of 0.8L from the origin (laser_approx).
async sub ecir00_at(a0: angle, step: angle) {
    var shots: int = 11;
    var gap: int = 7;
    var speed: fx = 2.7fx;
    var rod: fx = 102.4fx;
    if global(GVAR_RANK) == RANK_NORMAL {
        shots = 16;
        gap = 5;
        speed = 3.0fx;
        rod = 102.4fx;
    } else if global(GVAR_RANK) == RANK_HARD {
        shots = 20;
        gap = 4;
        speed = 4.0fx;
        rod = 115.2fx;
    } else if global(GVAR_RANK) >= RANK_LUNATIC {
        shots = 24;
        gap = 4;
        speed = 5.0fx;
        rod = 128fx;
    }
    var a: angle = a0;
    for i in 0..shots {
        var h: int = laser(LASER_COLOR, $self_x, $self_y, a, 0fx, 7fx, 0, 600, 0);
        lz_speed(h, speed, rod);
        a = a + step;
        wait(gap);
    }
}

// ECir00: setHurtbox(24,24)=r12, setHitbox(16,16)=r8.
// moveVel(ANGLE_PLAYER,3) then moveSpeedTime(40,1,0): quad-in to 0.
// 40 frames later the laser fan task starts; 60 more frames later a new
// ANGLE_PLAYER reading and speed 0->2 over 120 frames.
async sub ecir00(a0: angle, step: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    move_vel(0, aim_player(), 3fx, EASE_LINEAR);
    move_speed(40, 0fx, EASE_QUAD_IN);
    wait(40);
    spawn ecir00_at(a0, step);
    wait(60);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);
    move_speed(120, 2fx, EASE_QUAD_IN);
    loop { wait(1000); }
}

// MainSub00: both streams, then the ECir00 pair 60 frames later.
// F0/F1 per rank: F0=pi (x=+96) / 0 (x=-96); |F1| = 24/20/18/15 deg.
async sub wave_pattern() {
    wait(OPENING_BUFFER);
    var firing: int = 0;
    if global(GVAR_RANK) >= RANK_HARD {
        firing = 1;
    }
    spawn phantom_stream_left(firing);
    spawn phantom_stream_right(firing);
    wait(60);
    var f1: angle = 24deg;
    if global(GVAR_RANK) == RANK_NORMAL {
        f1 = 20deg;
    } else if global(GVAR_RANK) == RANK_HARD {
        f1 = 18deg;
    } else if global(GVAR_RANK) >= RANK_LUNATIC {
        f1 = 15deg;
    }
    _ = spawn_enemy(96fx, -32fx, 240, 0, 0, 0, ecir00(180deg, 0deg - f1));
    _ = spawn_enemy(-96fx, -32fx, 240, 0, 0, 0, ecir00(0deg, f1));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

